// Simple in-memory storage for demo purposes
// In a real app, you'd use a proper database

interface User {
  id: string;
  email: string;
  name: string;
  password?: string; // In real app, this would be hashed
  productionAccessApproved: boolean;
}

class InMemoryDB {
  private users: User[] = [
    {
      id: '1',
      email: 'admin@example.com',
      name: 'Admin User',
      password: '$2a$10$8K1p/a0SIuTGZBhpZuzxZOYq8YEGP18/YkYNWdOvM5ebEa1OD/WjW', // 'password123' hashed
      productionAccessApproved: true
    }
  ];

  getUserByEmail(email: string): User | undefined {
    return this.users.find(user => user.email === email);
  }

  getUserById(id: string): User | undefined {
    return this.users.find(user => user.id === id);
  }

  addUser(user: Omit<User, 'id'>): User {
    const newUser = {
      ...user,
      id: Date.now().toString()
    };
    this.users.push(newUser);
    return newUser;
  }

  getAllUsers(): User[] {
    return [...this.users]; // Return a copy
  }
}

export const db = new InMemoryDB();